package cl.skinspad.ticket.soporte;
import java.time.*;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.format.annotation.DateTimeFormat;import com.fasterxml.jackson.databind.JsonNode;import static cl.skinspad.ticket.soporte.SoporteDtos.*;
@RestController @RequestMapping("/api") @RequiredArgsConstructor public class SoporteController {
 private final SoporteIdentidad identidad;private final SoporteRegistro registro;private final TicketService tickets;private final SoporteAdjuntoRepository adjuntos;private final BandejaRepository bandeja;private final SoporteStats stats;private final SoporteJson json;
 @GetMapping("/soporte/notificaciones") public List<Aviso> notificaciones(@RequestHeader(value="Authorization",required=false)String auth){return registro.avisos(identidad.validar(auth,false));}
 private void comprobar(String tipo,Long id,SoporteIdentidad.Actor a){switch(tipo){case "TICKET"->tickets.acceso(id,a);case "ADJUNTO"->{var f=adjuntos.findById(id).orElseThrow(()->new jakarta.persistence.EntityNotFoundException("Adjunto no encontrado"));comprobar(f.getEntidad(),f.getEntidadId(),a);}default->throw new IllegalArgumentException("Tipo inválido");}}
 @GetMapping("/soporte/acceso") public Map<String,Boolean> acceso(@RequestHeader(value="Authorization",required=false)String auth,@RequestParam String tipo,@RequestParam Long id){comprobar(tipo,id,identidad.validar(auth,false));return Map.of("permitido",true);}
 @GetMapping("/tickets/adjuntos/{id}") public ResponseEntity<byte[]> adjunto(@PathVariable Long id,@RequestHeader(value="Authorization",required=false)String auth){var a=identidad.validar(auth,false);comprobar("ADJUNTO",id,a);var f=adjuntos.findById(id).orElseThrow();return ResponseEntity.ok().contentType(MediaType.parseMediaType(f.getMime())).header("Content-Disposition",ContentDisposition.attachment().filename("evidencia-"+id+(f.getMime().equals("image/png")?".png":".jpg")).build().toString()).header("X-Content-Type-Options","nosniff").header("Content-Security-Policy","default-src 'none'; sandbox").header("Cache-Control","no-store").body(f.getDatos());}
 @GetMapping("/admin/tickets") public Pagina bandeja(@RequestHeader(value="Authorization",required=false)String auth,@RequestParam(required=false)String clase,@RequestParam(required=false)String estado,@RequestParam(required=false)String prioridad,@RequestParam(required=false)String tipo,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate desde,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate hasta,@RequestParam(defaultValue="0")int pagina,@RequestParam(defaultValue="20")int tamano,jakarta.servlet.http.HttpServletRequest request){identidad.validar(auth,true);return bandeja.buscar("TICKET",estado,prioridad,tipo,desde,hasta,pagina,tamano);}
 @GetMapping("/admin/soporte/stats") public SoporteStats.Resumen stats(@RequestHeader(value="Authorization",required=false)String auth){identidad.validar(auth,true);return stats.obtener();}
}